def min_duration(a, b, c, d):
    # Sort the initial positions to simplify the calculation
    positions = sorted([a, b, c])

    # Calculate the current distances between each pair of ropewalkers
    current_distances = [positions[i] - positions[j] for i in range(1, len(positions)) for j in range(i)]

    # If the current distances are already greater than or equal to d, return 0
    if all(distance >= d for distance in current_distances):
        return 0

    # Otherwise, calculate the minimum number of steps required
    steps = 0
    while True:
        # Find the farthest two ropewalkers
        max_distance = max(current_distances)

        # Move the farthest ropewalker in the direction to increase the distance
        if max_distance == positions[2] - positions[0]:
            if positions[1] > positions[0]:
                positions[1] -= 1
            else:
                positions[1] += 1
        elif max_distance == positions[2] - positions[1]:
            if positions[1] < positions[0]:
                positions[1] -= 1
            else:
                positions[1] += 1
        elif max_distance == positions[2] - positions[2]:
            if positions[2] < positions[1]:
                positions[2] -= 1
            else:
                positions[2] += 1

        # Update the distances
        current_distances = [positions[i] - positions[j] for i in range(1, len(positions)) for j in range(i)]

        # Increment the step counter
        steps += 1

        # Check if the distances are now sufficient
        if all(distance >= d for distance in current_distances):
            return steps

# Example usage
print(min_duration(5, 2, 6, 3))  # Output: 2
print(min_duration(3, 1, 5, 6))  # Output: 8
